"""Generate separate static reference pages, without adding app startup downloads."""
from pathlib import Path
import html,json,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'_site';BASE='https://guidufox.github.io/breach-r6-atlas/'
escape=lambda v:html.escape(str(v),quote=True)
STYLE='''body{margin:0;background:#101417;color:#e7edf0;font:16px/1.65 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:28px 22px}a{color:#f5cf55}h1{line-height:1.2;font-size:clamp(28px,5vw,42px)}h2{margin-top:30px}nav{display:flex;flex-wrap:wrap;gap:16px}.notice{border:1px solid #44515b;padding:14px;border-radius:8px;color:#bccad3}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.cards a{padding:15px;border:1px solid #44515b;border-radius:8px;text-decoration:none}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:10px;border-bottom:1px solid #34414b}th{color:#f5cf55}footer{margin-top:35px;padding-top:18px;border-top:1px solid #34414b;font-size:13px;color:#a4b4bf}.primary{display:inline-block;padding:12px 18px;border-radius:7px;background:#f5cf55;color:#111;text-decoration:none;font-weight:700}button{font:inherit;padding:10px;background:#f5cf55;border:0;border-radius:6px;color:#111;cursor:pointer}input{font:inherit}p{max-width:85ch}code{overflow-wrap:anywhere}'''
NOTICE='Proyecto comunitario, no afiliado ni aprobado por Ubisoft o R6Calls. Marcas y material ajeno pertenecen a sus titulares.'
def page(title,description,url,body):
 markup='<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+escape(description)+'"><title>'+escape(title)+'</title><link rel="canonical" href="'+escape(url)+'"><meta property="og:type" content="website"><meta property="og:title" content="'+escape(title)+'"><meta property="og:description" content="'+escape(description)+'"><meta property="og:url" content="'+escape(url)+'"><meta property="og:image" content="'+BASE+'social-card.png"><link rel="stylesheet" href="'+BASE+'guide.css"><link rel="icon" href="'+BASE+'r6-logo.png"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'self\'; style-src \'self\'; img-src \'self\' data:; connect-src \'self\' https://r6-flamingo-team-service.stony-elk-7524.chatgpt.site; base-uri \'none\'; form-action \'none\'; object-src \'none\'"></head><body><main><nav><a href="'+BASE+'">Atlas interactivo</a><a href="'+BASE+'mapas/">Todos los mapas</a><a href="'+BASE+'legal.html">Privacidad y derechos</a></nav>'+body+'<footer>'+NOTICE+' <a href="https://github.com/Guidufox/breach-r6-atlas/issues/new">Contacto y retirada</a> · <a href="https://www.r6calls.com/">Fuente: R6Calls</a></footer></main><script src="'+BASE+'metrics.js"></script></body></html>'
 start=markup.index('<meta http-equiv="Content-Security-Policy"')
 end=markup.index('>',start)+1
 policy=markup[start:end]
 return (markup[:start]+markup[end:]).replace('<head>','<head>'+policy,1)

def floor_name(floor,maximum):
 return 'Subsuelo' if floor==-1 else 'Sótano' if floor==0 else 'Azotea' if floor==maximum and floor>1 else 'Planta baja' if floor==1 else f'Piso {floor-1}'
def build():
 policy=json.loads((ROOT/'content-policy.json').read_text());catalog=json.loads((ROOT/'data.js').read_text().split('=',1)[1].rstrip(';\n'));urls=[BASE,BASE+'legal.html'];(OUT/'guide.css').write_text(STYLE)
 if policy.get('mapsEnabled',True):
  (OUT/'mapas').mkdir(exist_ok=True);cards=[]
  for m in catalog['maps']:
   ident=m['id'];name=m.get('names',{}).get('es',m['name']);folder=OUT/'mapas'/ident;folder.mkdir(exist_ok=True);url=BASE+'mapas/'+ident+'/';urls.append(url);cards.append('<a href="'+url+'">'+escape(name)+' · '+str(len(m['labels']))+' callouts</a>')
   body='<h1>Callouts de '+escape(name)+' en español</h1><p>Referencia comunitaria de '+escape(m['name'])+' con nombres en español, inglés y portugués de Brasil. Abrí el mapa interactivo para ubicar cada punto, estudiar nombres y preparar rutas con tu equipo.</p><p><a class="primary" href="'+BASE+'?map='+ident+'&amp;lang=es">Abrir '+escape(name)+' y preparar una táctica</a></p><p class="notice">'+NOTICE+' Los nombres de habitaciones proceden de R6Calls; no se presentan como nombres oficiales del HUD. Datos de referencia consultados el '+escape(catalog['nameResearch']['date'])+'. Revisión de fuente: '+str(m['revision'])+'.</p>'
   for floor in sorted({label['floor'] for label in m['labels']}):
    body+='<h2>'+floor_name(floor,m.get('maxFloorNumber',max(m['floors'] or [1])))+'</h2><div class="table-wrap"><table><thead><tr><th>Español</th><th>English</th><th>Português (BR)</th></tr></thead><tbody>'
    for label in sorted((l for l in m['labels'] if l['floor']==floor),key=lambda l:l.get('names',{}).get('es',l['name'])):
     body+='<tr>'+''.join('<td>'+escape(label.get('names',{}).get(lang,label['name']))+'</td>' for lang in ['es','en','pt-br'])+'</tr>'
    body+='</tbody></table></div>'
   (folder/'index.html').write_text(page('Callouts de '+name+' · Flamingo/Strat', 'Nombres comunitarios de '+name+' en español, inglés y portugués; referencia por piso y enlace a mapas y tácticas.',url,body),encoding='utf-8')
  body='<h1>Mapas y callouts de Rainbow Six Siege</h1><p>Flamingo/Strat ayuda a amigos y equipos de cinco a aprender los nombres de los mapas, practicar callouts y preparar tareas, rutas y entradas. Estas guías tienen texto de referencia; los dibujos y la colaboración están en el atlas interactivo.</p><p class="notice">'+NOTICE+'</p><div class="cards">'+''.join(cards)+'</div>'
  (OUT/'mapas/index.html').write_text(page('Guías de callouts · Flamingo/Strat','29 referencias comunitarias de mapas de Rainbow Six Siege, con callouts por piso en tres idiomas.',BASE+'mapas/',body),encoding='utf-8');urls.append(BASE+'mapas/')
 else:
  body='<h1>Flamingo/Strat</h1><p>La distribución de mapas está suspendida.</p><p>'+escape(policy.get('notice','Contenido retirado para revisión de derechos.'))+'</p>'
  (OUT/'index.html').write_text(page('Flamingo/Strat · contenido en revisión','Contenido suspendido para revisión.',BASE,body),encoding='utf-8')
 legal='<h1>Privacidad, créditos y derechos</h1><p class="notice">'+NOTICE+'</p><h2>Para qué sirve</h2><p>Herramienta comunitaria para aprender callouts y preparar tácticas entre amigos, sin anuncios ni cobros. Este aviso y el uso gratuito no equivalen a autorización de todos los recursos.</p><h2>Derechos y licencias</h2><p>Código propio: MIT. Mapas y callouts: R6Calls, con aviso de licencia de origen conservado. Emblemas, nombres y marcas: sus respectivos titulares. No se afirma permiso comercial sobre material de Ubisoft u otros titulares.</p><p><a href="https://github.com/Guidufox/breach-r6-atlas/issues/1">Solicitud de permiso a R6Calls: pendiente de respuesta</a>.</p><h2>Trabajo personal y salas</h2><p>Las preferencias, notas y dibujos personales se guardan en este navegador. Solo al crear o entrar a una sala se comparte la táctica del mapa elegido y el apodo. El acceso a las salas caduca a las dos horas; los registros vencidos se limpian con nueva actividad del servicio. Eliminar copias físicas puede ocurrir después de la caducidad. El trabajo personal se restaura al salir. Compartí las invitaciones solo con el equipo y exportá para conservar el plan.</p><h2>Webhook opcional</h2><p>No hay bot de Discord. El webhook solo se usa cuando lo pegás y pulsás Enviar; no se guarda en preferencias ni respaldos y se borra al cerrar el diálogo. Discord aplica su política al mensaje y a los archivos recibidos.</p><h2>Métricas sin cookies de seguimiento</h2><p>Un contador propio registra fecha UTC, ruta de página e idioma, con totales agregados. No guarda IP ni identificadores de visitantes en su tabla, y no recibe tácticas, búsquedas, query strings, fragmentos, invitaciones ni webhooks. Respeta Do Not Track y Global Privacy Control. Cuenta visitas, no personas únicas. El alojamiento puede tratar registros técnicos bajo sus propias políticas.</p><h2>Contacto y retirada</h2><p><a href="https://github.com/Guidufox/breach-r6-atlas/issues/new">GitHub Issues: consultas, correcciones y retirada</a>. Responsable del proyecto y de revisión de temporadas: Guidufox. Hay un procedimiento para suspender recursos reclamados; no se promete borrar todas las copias, forks o cachés instantáneamente.</p><p>Documentación: <a href="https://github.com/Guidufox/breach-r6-atlas/blob/main/docs/RIGHTS.md">Derechos</a> · <a href="https://github.com/Guidufox/breach-r6-atlas/blob/main/docs/PRIVACY.md">Privacidad</a> · <a href="https://github.com/Guidufox/breach-r6-atlas/blob/main/docs/TAKEDOWN.md">Retirada</a>.</p>'
 (OUT/'legal.html').write_text(page('Privacidad y derechos · Flamingo/Strat','Créditos, licencias separadas, privacidad, almacenamiento y contacto de retirada del proyecto comunitario.',BASE+'legal.html',legal),encoding='utf-8')
 ns='http://www.sitemaps.org/schemas/sitemap/0.9';ET.register_namespace('',ns);site=ET.Element('{'+ns+'}urlset')
 for url in urls:item=ET.SubElement(site,'{'+ns+'}url');ET.SubElement(item,'{'+ns+'}loc').text=url
 ET.ElementTree(site).write(OUT/'sitemap.xml',encoding='utf-8',xml_declaration=True)
 if not (OUT/'r6-logo.png').exists():
  for htmlfile in OUT.rglob('*.html'):
   import re
   htmlfile.write_text(re.sub(r'<link rel="(?:icon|shortcut icon)"[^>]*>', '',htmlfile.read_text()))
 (OUT/'robots.txt').write_text('User-agent: *\nAllow: /breach-r6-atlas/\nSitemap: '+BASE+'sitemap.xml\n')
 print('Static SEO pages:',len(urls))
if __name__=='__main__':build()
